package br.gov.go.ppgo.espp.service; import org.springframework.stereotype.Service; import java.text.Normalizer; import java.util.Locale; import java.util.function.Predicate;
@Service public class SlugService { public String base(String s){ var x=Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-+|-+$)",""); return x.length()>80?x.substring(0,80):x; } public String unico(String s,Predicate<String> existe){ var b=base(s); if(!existe.test(b))return b; int n=2; while(existe.test(b+"-"+n))n++; return b+"-"+n; } }